import io.github.diodeme.ji.agent.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.testkit.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
class FirstRejectExecutor extends AbstractExecutorService {
  final AtomicBoolean first = new AtomicBoolean(true);
  final ExecutorService delegate = Executors.newSingleThreadExecutor();
  volatile boolean shutdown;
  public void execute(Runnable task) { if (first.getAndSet(false)) throw new RejectedExecutionException("first submit rejected"); delegate.execute(task); }
  public void shutdown() { shutdown = true; delegate.shutdown(); }
  public List<Runnable> shutdownNow() { shutdown = true; return delegate.shutdownNow(); }
  public boolean isShutdown() { return shutdown; }
  public boolean isTerminated() { return delegate.isTerminated(); }
  public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException { return delegate.awaitTermination(timeout, unit); }
}
var provider = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Text("done"), new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
var store = new MemoryHostStore();
var permissions = new PermissionBroker(Clock.systemUTC());
var executor = new FirstRejectExecutor();
var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(store).permissionDecider(permissions).executor(executor).build();
var sessions = new SessionApplicationService(runtime);
var sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
var prompts = new PromptApplicationService(sessions, store);
try { prompts.prompt(sessionId, "command-1", "hello"); System.out.println("FIRST_UNEXPECTED_SUCCESS"); } catch (Throwable failure) { System.out.println("FIRST_FAILURE=" + failure.getClass().getSimpleName() + ":" + failure.getMessage()); }
var hash = PromptApplicationService.sha256("hello".getBytes(java.nio.charset.StandardCharsets.UTF_8));
System.out.println("JOURNAL_PRESENT_AFTER_START_FAILURE=" + store.command(sessionId, "command-1", hash).isPresent());
System.out.println("ACTIVE_AFTER_START_FAILURE=" + sessions.hasActiveRun(sessionId));
try { var retry = prompts.prompt(sessionId, "command-1", "hello"); System.out.println("RETRY_RUN_PRESENT=" + retry.run().isPresent()); } catch (Throwable failure) { System.out.println("RETRY_FAILURE=" + failure.getClass().getSimpleName() + ":" + failure.getMessage()); }
sessions.close(); executor.shutdownNow();
/exit
